const rawSheets = $input.first().json.sheets || [];
const results = [];

function parseSheetTitle(title) {
  if (!title) return null;
  const cleanTitle = title.trim().replace(/\s+/g, ' ');

  // 1. Patrón: "Materia Grado-Curso" (ej: "Física 10-A", "Fisica 10A", "Matemáticas 9-1", "Lengua 11 B")
  const pattern1 = /^(.+?)[,\s_-]+(\d{1,2})[\s._-]*([A-Za-z0-9])$/i;

  // 2. Patrón invertido: "Grado-Curso Materia" (ej: "10-A Física", "10A Fisica", "9-1 Matematicas")
  const pattern2 = /^(\d{1,2})[\s._-]*([A-Za-z0-9])[,\s_-]+(.+)$/i;

  // 3. Patrón grados sin letra (ej: "Física 10", "Matemáticas 11")
  const pattern3 = /^(.+?)[,\s_-]+(\d{1,2})$/i;

  let match = cleanTitle.match(pattern1);
  if (match) {
    return {
      materia: match[1].trim(),
      curso: `${match[2]}-${match[3].toUpperCase()}`
    };
  }

  match = cleanTitle.match(pattern2);
  if (match) {
    return {
      materia: match[3].trim(),
      curso: `${match[1]}-${match[2].toUpperCase()}`
    };
  }

  match = cleanTitle.match(pattern3);
  if (match) {
    return {
      materia: match[1].trim(),
      curso: match[2].trim()
    };
  }

  return null;
}

for (const sheet of rawSheets) {
  const title = sheet.properties?.title?.trim() || "";

  if (title.toLowerCase().startsWith('config') || title.toLowerCase().startsWith('resumen')) {
    continue;
  }

  const parsed = parseSheetTitle(title);

  if (parsed) {
    results.push({
      sheetName: title,
      materia: parsed.materia,
      curso: parsed.curso,
      sheetId: sheet.properties?.sheetId,
      status: "VALID"
    });
  } else {
    results.push({
      sheetName: title,
      status: "REJECTED",
      warning: `No se pudo identificar la materia y el curso en la hoja '${title}'. Asegúrate de incluir el nombre de la materia y el grupo (Ej: 'Física 10-A', 'Fisica 10A' o '10-A Física').`
    });
  }
}

return results.map(item => ({ json: item }));

const items = $input.all();
// Lee directamente los metadatos de la hoja actual del Loop
const currentSheet = $('Loop Over Items').item.json;
const sheetName = currentSheet.sheetName || "Hoja";
const materia = currentSheet.materia || "";
const curso = currentSheet.curso || "";

const calificacionesValidas = [];
const advertencias = [];

function parseNota(val, campo, rowNum, sName) {
  if (val === null || val === undefined || val === '') return null;
  const num = parseFloat(String(val).replace(',', '.'));
  if (isNaN(num) || num < 0.0 || num > 5.0) return null;
  return Math.round(num * 100) / 100;
}

for (let i = 0; i < items.length; i++) {
  const row = items[i].json;
  const rowNum = row.row_number;
  const email = (row.col_3 || "").trim().toLowerCase();

  // Ignorar encabezados o filas vacías
  if (!email || !email.includes('@') || rowNum < 7) {
    continue;
  }

  calificacionesValidas.push({
    sheetName: sheetName,
    materia: materia,
    curso: curso,
    estudiante: row.col_2,
    email: email,
    row_number: rowNum,
    notas: {
      bimestral: parseNota(row.col_4, "Bimestral", rowNum, sheetName),
      actitudinal: parseNota(row.col_10, "Actitudinal", rowNum, sheetName),
      cuaderno: parseNota(row.col_12, "Cuaderno", rowNum, sheetName),
      evidencia_1: parseNota(row.col_24, "Evidencia 1", rowNum, sheetName),
      evidencia_2: parseNota(row.col_36, "Evidencia 2", rowNum, sheetName),
      evidencia_3: parseNota(row.col_48, "Evidencia 3", rowNum, sheetName),
      definitiva: parseNota(row.col_50, "Definitiva", rowNum, sheetName)
    },
    status: "VALID_ROW"
  });
}

return [
  ...calificacionesValidas.map(c => ({ json: c })),
  ...advertencias.map(a => ({ json: a }))
];
